      'bg-action-disabled-btn', '!bg-action-disabled-btn', 'pointer-events-none', 'text-action-disabled-disabled');
    (enabled ? ENABLED_BTN : DISABLED_BTN).split(' ').forEach(function (cls) {
      if (cls) btn.classList.add(cls);
